//Using jasmine
(function(outputs, steps, params, stepResult, assertEqual) {
	//setup
	var ohsmUtils = new x_hccc_hoc_ohs.HoCOHSMUtils();

	var locationBuildingSysId = steps('3b33bda01b77a1d49fde86acdd4bcb96').record_id;
	var locationRoomSysId = steps('7d961f0a1b37ed189fde86acdd4bcb73').record_id;
	
	var OHSM_CASES = {
		WITH_LOCATION: steps('ea13ad6c1bb3a1d49fde86acdd4bcb95').record_id,
		WITH_LOCATION_ROOM: steps('a6690b1a1b33e994893442a7bc4bcbe6').record_id,
		WITH_LOCATION_AREA: steps('64dc5d321b73e9589fde86acdd4bcb01').record_id,
		WITH_LOCATION_DETAILS: steps('0c7d91b61b73e9589fde86acdd4bcb17').record_id,
		WITH_LOCATION_AREA_DETAILS: steps('7d7d1d761b73e9589fde86acdd4bcb17').record_id,
		WITH_LOCATION_ROOM_AREA: steps('6d8e11ba1b73e9589fde86acdd4bcb1f').record_id,
		WITH_LOCATION_ROOM_DETAILS: steps('bf7e11ba1b73e9589fde86acdd4bcbb6').record_id,
		WITH_LOCATION_ROOM_AREA_DETAILS: steps('63fd553a1b73e9589fde86acdd4bcbc1').record_id,
		WITHOUT_LOCATION: steps('9b7025fe1b73e9589fde86acdd4bcbc7').record_id
	};

	var caseGr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');

	var locationGr = new GlideRecord('cmn_location');
	locationGr.get(locationBuildingSysId);
	var roomGr = new GlideRecord('cmn_location');
	roomGr.get(locationRoomSysId);


	//tests
	describe('using a glideRecord', function() {
		describe('that contains location, street, room, area and details', function(){
			it('should return the full address and details', function() {
				caseGr.get(OHSM_CASES.WITH_LOCATION_ROOM_AREA_DETAILS);
				var locationString = ohsmUtils.getLocationString(caseGr);
				var expectedOutput = locationGr.getDisplayValue('name')+"("+locationGr.getDisplayValue('street')+")";
				expectedOutput += '\n' + roomGr.getDisplayValue('name');
				expectedOutput += '\n' + caseGr.getDisplayValue('inc_location_area');
				expectedOutput += '\n' + caseGr.getDisplayValue('inc_specific_location');
				
				expect(locationString).toBe(expectedOutput);
			});
		});
		describe('that contains location (and street)', function(){
			it('should return basic details', function() {
				caseGr.get(OHSM_CASES.WITH_LOCATION);
				var locationString = ohsmUtils.getLocationString(caseGr);
				expect(locationString).toBe(locationGr.getDisplayValue('name')+"("+locationGr.getDisplayValue('street')+")");
			});
		});
		describe('that contains location and room', function(){
			it('should return basic details', function() {
				caseGr.get(OHSM_CASES.WITH_LOCATION_ROOM);
				var locationString = ohsmUtils.getLocationString(caseGr);
				var expectedOutput = locationGr.getDisplayValue('name')+"("+locationGr.getDisplayValue('street')+")";
				expectedOutput += '\n' + roomGr.getDisplayValue('name');
				
				expect(locationString).toBe(expectedOutput);
			});
		});
		describe('that contains location and area', function(){
			it('should return basic details', function() {
				caseGr.get(OHSM_CASES.WITH_LOCATION_AREA);
				var locationString = ohsmUtils.getLocationString(caseGr);
				var expectedOutput = locationGr.getDisplayValue('name')+"("+locationGr.getDisplayValue('street')+")";
				expectedOutput += '\n' + caseGr.getDisplayValue('inc_location_area');
				
				expect(locationString).toBe(expectedOutput);
			});
		});
		describe('that contains location and details', function(){
			it('should return basic details', function() {
				caseGr.get(OHSM_CASES.WITH_LOCATION_DETAILS);
				var locationString = ohsmUtils.getLocationString(caseGr);
				var expectedOutput = locationGr.getDisplayValue('name')+"("+locationGr.getDisplayValue('street')+")";
				expectedOutput += '\n' + caseGr.getDisplayValue('inc_specific_location');
				
				expect(locationString).toBe(expectedOutput);
			});
		});
		describe('that contains location, area and details', function(){
			it('should return basic details', function() {
				caseGr.get(OHSM_CASES.WITH_LOCATION_AREA_DETAILS);
				var locationString = ohsmUtils.getLocationString(caseGr);
				var expectedOutput = locationGr.getDisplayValue('name')+"("+locationGr.getDisplayValue('street')+")";
				expectedOutput += '\n' + caseGr.getDisplayValue('inc_location_area');
				expectedOutput += '\n' + caseGr.getDisplayValue('inc_specific_location');
				
				expect(locationString).toBe(expectedOutput);
			});
		});
		describe('that contains location, room and details', function(){
			it('should return basic details', function() {
				caseGr.get(OHSM_CASES.WITH_LOCATION_ROOM_DETAILS);
				var locationString = ohsmUtils.getLocationString(caseGr);
				var expectedOutput = locationGr.getDisplayValue('name')+"("+locationGr.getDisplayValue('street')+")";
				expectedOutput += '\n' + roomGr.getDisplayValue('name');
				expectedOutput += '\n' + caseGr.getDisplayValue('inc_specific_location');
				
				expect(locationString).toBe(expectedOutput);
			});
		});
		describe('that contains location, room an area', function(){
			it('should return basic details', function() {
				caseGr.get(OHSM_CASES.WITH_LOCATION_ROOM_AREA);
				var locationString = ohsmUtils.getLocationString(caseGr);
				var expectedOutput = locationGr.getDisplayValue('name')+"("+locationGr.getDisplayValue('street')+")";
				expectedOutput += '\n' + roomGr.getDisplayValue('name');
				expectedOutput += '\n' + caseGr.getDisplayValue('inc_location_area');
				
				expect(locationString).toBe(expectedOutput);
			});
		});
		/*describe('that does contains no location', function(){
			it('should throw an error', function() {
				caseGr.get(OHSM_CASES.WITHOUT_LOCATION);
				expect(function(){
					var locationString = ohsmUtils.getLocationString(caseGr);
					stepResult.setOutputMessage("expecting to throw but instead we have: " + locationString);
				}).toThrow();
			});
		});*/ //currently the function will work and return all other info available
	});
})(outputs, steps, params, stepResult, assertEqual);
jasmine.getEnv().execute();
